<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Str;use App\Services\Commerce;use App\Services\KetuaPesapal;
class CommerceController extends Controller {
 public function wallet(){return response()->json(['status'=>true,'gift_coins'=>(int)(auth('app_users')->user()?->wallet ?? 0),'wallets'=>DB::table('cash_wallets')->where('user_id',auth('app_users')->user()?->id)->get(['currency_code','balance_minor','frozen']),'coin_packs'=>DB::table('super_like_packs')->where('reward_type','coins')->where('enabled',true)->get(),'payments_available'=>app(KetuaPesapal::class)->configured(),'pending_orders'=>DB::table('commerce_orders')->where('user_id',auth('app_users')->user()?->id)->where('kind','topup')->where('status','pending')->orderByDesc('created_at')->limit(10)->get(['id','idempotency_key','amount_minor','created_at']),'transactions'=>DB::table('cash_ledger')->where('user_id',auth('app_users')->user()?->id)->orderByDesc('id')->limit(50)->get(['currency_code','amount_minor','kind','created_at'])]);}
 private function validated(Request $r):array{return $r->validate(['kind'=>'required|in:topup,plan,pack,ticket,content','item_id'=>'nullable|string|max:80','period_days'=>'nullable|integer|min:1|max:366','currency_code'=>'required|regex:/^[A-Z]{3}$/|exists:currencies,code','amount_minor'=>'nullable|integer|min:1|max:1000000000','expected_amount_minor'=>'nullable|integer|min:1|max:1000000000','idempotency_key'=>'required|uuid']);}
 private function order(array $v,int $id){$old=DB::table('commerce_orders')->where('user_id',$id)->where('idempotency_key',$v['idempotency_key'])->first();if($old){if($old->kind!==$v['kind'] || (string)$old->item_id!==(string)($v['item_id']??'') || $old->currency_code!==$v['currency_code'] || ($v['kind']==='topup' && $old->amount_minor!=($v['amount_minor']??0)) || ($v['kind']==='plan' && $old->period_days!=($v['period_days']??30)))throw new \DomainException('Checkout retry conflicts with original purchase');return $old;}
  $price=Commerce::price($v,$id);if(isset($v['expected_amount_minor']) && $price['amount_minor']!=$v['expected_amount_minor'])throw new \DomainException('Price changed. Refresh before buying.');$uuid=(string)Str::uuid();DB::table('commerce_orders')->insert(['id'=>$uuid,'user_id'=>$id,'idempotency_key'=>$v['idempotency_key'],'kind'=>$v['kind'],'item_id'=>$v['item_id']??null,'period_days'=>$v['period_days']??null,'currency_code'=>$v['currency_code'],'amount_minor'=>$price['amount_minor'],'snapshot'=>$price['snapshot'],'created_at'=>now(),'updated_at'=>now()]);return DB::table('commerce_orders')->find($uuid);
 }
 public function purchase(Request $r){$v=$this->validated($r);$id=auth('app_users')->user()?->id;if($v['kind']==='topup')return response()->json(['status'=>false,'message'=>'Use mobile money to top up.'],422);
  try{return DB::transaction(function()use($v,$id){DB::table('users')->where('id',$id)->lockForUpdate()->first();$o=$this->order($v,$id);if($o->status==='settled')return response()->json(['status'=>true,'order_id'=>$o->id,'message'=>'Already purchased.']);if($o->status!=='pending')throw new \DomainException('Order unavailable');$wallet=DB::table('cash_wallets')->where('user_id',$id)->where('currency_code',$o->currency_code)->lockForUpdate()->first();if(!$wallet || $wallet->frozen || $wallet->balance_minor<$o->amount_minor)throw new \DomainException('Insufficient account balance. Top up first.');DB::table('cash_wallets')->where('id',$wallet->id)->decrement('balance_minor',$o->amount_minor);Commerce::apply($o);DB::table('cash_ledger')->insert(['order_id'=>$o->id,'user_id'=>$id,'currency_code'=>$o->currency_code,'amount_minor'=>-$o->amount_minor,'kind'=>$o->kind,'created_at'=>now(),'updated_at'=>now()]);DB::table('commerce_orders')->where('id',$o->id)->update(['status'=>'settled','updated_at'=>now()]);return response()->json(['status'=>true,'order_id'=>$o->id,'message'=>'Purchase complete.']);});}catch(\DomainException $e){return response()->json(['status'=>false,'message'=>$e->getMessage()],409);}
 }
 public function topup(Request $r){$v=$this->validated($r);if($v['kind']!=='topup')return response()->json(['status'=>false],422);$provider=app(KetuaPesapal::class);if(!$provider->configured())return response()->json(['status'=>false,'message'=>'Mobile money unavailable.'],503);$me=auth('app_users')->user();try{$o=DB::transaction(function()use($v,$me){DB::table('users')->where('id',$me->id)->lockForUpdate()->first();return $this->order($v,$me->id);});return Cache::lock('ketua.checkout.'.$o->id,40)->block(3,function()use($o,$me,$provider){$current=DB::table('commerce_orders')->find($o->id);if($current->status==='settled')return response()->json(['status'=>true,'order_id'=>$o->id,'settled'=>true]);if(!$current->checkout_url){$b=$provider->start($current,$me);DB::table('commerce_orders')->where('id',$o->id)->update(['tracking_id'=>$b['order_tracking_id'],'checkout_url'=>$b['redirect_url'],'updated_at'=>now()]);$current=DB::table('commerce_orders')->find($o->id);}return response()->json(['status'=>true,'order_id'=>$current->id,'checkout_url'=>$current->checkout_url]);});}catch(\DomainException $e){return response()->json(['status'=>false,'message'=>$e->getMessage()],409);}catch(\Throwable $e){\Log::warning('KETUA payment initiation unavailable',['exception'=>get_class($e)]);return response()->json(['status'=>false,'message'=>'Checkout could not start. Retry with the same request.'],503);}}
 public function status(Request $r){$v=$r->validate(['order_id'=>'required|uuid']);$o=DB::table('commerce_orders')->where('id',$v['order_id'])->where('user_id',auth('app_users')->user()?->id)->first();if(!$o)return response()->json(['status'=>false],404);if($o->tracking_id){try{Commerce::reconcile($o->id,app(KetuaPesapal::class)->status($o->tracking_id));}catch(\Throwable $e){return response()->json(['status'=>false,'message'=>'Verification unavailable. Your order is retained.'],503);}}return response()->json(['status'=>true,'data'=>DB::table('commerce_orders')->where('id',$o->id)->first(['id','status','currency_code','amount_minor','kind'])]);}
 public function ipn(Request $r){$tracking=$r->input('OrderTrackingId');$reference=$r->input('OrderMerchantReference');if(!is_string($tracking)||strlen($tracking)>120 || !is_string($reference)||strlen($reference)>80)return response()->json(['status'=>false],422);$o=DB::table('commerce_orders')->where('id',$reference)->where('tracking_id',$tracking)->first();if(!$o)return response()->json(['status'=>false],404);try{Commerce::reconcile($o->id,app(KetuaPesapal::class)->status($tracking));return response()->json(['orderNotificationType'=>$r->input('OrderNotificationType','IPNCHANGE'),'orderTrackingId'=>$tracking,'orderMerchantReference'=>$reference,'status'=>200]);}catch(\Throwable $e){return response()->json(['status'=>false],503);}}
 public function callback(){return response('Return to KETUA and tap Check payment. Your account is updated only after payment verification.',200)->header('Content-Type','text/plain');}
}
